-- ============================================================
-- 庭園石組・作庭技法（テーマID: 19, category_id: 5）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(5, 19, '水を使わずに石・砂・苔などで山水を表現する日本庭園の様式はどれか。', '池泉回遊式', '枯山水（かれさんすい）', '露地式', '坪庭', 1, '枯山水（かれさんすい）は水を一切使わず、石・砂・苔などで山水・海などの自然を象徴的に表現する庭園様式です。禅宗寺院の方丈庭園に多く見られ、龍安寺の石庭が世界的に有名です。', 1, false),
(5, 19, '龍安寺の石庭（方丈庭園）の石の数はいくつか。', '12個', '13個', '15個', '17個', 2, '龍安寺の石庭には15個の石が5つのグループに配置されています。どこから見ても15個すべてを同時に見ることができないよう設計されており、「不完全性の美」として解釈されることもあります。', 1, false),
(5, 19, '日本最古の作庭書として知られる平安時代の書物はどれか。', '庭園秘抄', '作庭記（さくていき）', '山水並野形図', '庭造り秘伝書', 1, '「作庭記（さくていき）」は平安時代中期（11世紀）に書かれた日本最古の作庭書です。橘俊綱（たちばなのとしつな）の作とされ、石の立て方・水の引き方など庭園造りの技法が詳しく記されています。', 1, false),
(5, 19, '天龍寺の曹源池庭園（そうげんちていえん）を作庭した人物はだれか。', '小堀遠州', '夢窓疎石', '重森三玲', '善阿弥', 1, '天龍寺の曹源池庭園は室町時代の高僧・夢窓疎石（むそうそせき、1275〜1351年）が作庭しました。嵐山を借景とした池泉回遊式庭園で、国の特別名勝に指定されています。', 1, false),
(5, 19, '「借景（しゃっけい）」とはどのような作庭技法か。', '他の寺院の石を借りて使う技法', '庭の外の山や建物を庭の一部として取り込む技法', '水を借景として活用する技法', '他流派の技法を取り入れる技法', 1, '借景は庭の外に広がる山・木・建物などを庭の一部として取り込む作庭技法です。天龍寺の嵐山、円通寺の比叡山が借景の代表例です。庭を実際より広く豊かに見せる効果があります。', 1, false),
(5, 19, '桂離宮や二条城の庭園などを作庭した江戸時代初期の大名茶人はだれか。', '千利休', '古田織部', '小堀遠州', '武野紹鴎', 2, '小堀遠州（こぼりえんしゅう、1579〜1647年）は江戸幕府の作事奉行（さくじぶぎょう）として桂離宮・二条城・名古屋城の庭園作庭に携わった大名茶人・作庭家です。「綺麗さび」の美意識で知られます。', 2, false),
(5, 19, '「石立僧（いしたてそう）」とはどのような存在か。', '石仏を彫る僧侶', '石を用いた庭園造りを得意とした僧侶・作庭家', '石段の掃除を担当した僧侶', '石の守り神に祈りをささげる僧侶', 1, '石立僧（いしたてそう）は平安・鎌倉時代に石を立てる庭園作りを専門とした僧侶・作庭師の呼称です。庭石の配置を神聖な行為とし、風水的・宗教的な意味を持たせた作庭を行いました。作庭記にもその記述があります。', 2, false),
(5, 19, '東福寺方丈庭園を昭和時代に作庭した作庭家はだれか。', '小堀遠州', '夢窓疎石', '重森三玲', '善阿弥', 2, '東福寺の方丈庭園は昭和14年（1939年）に重森三玲（しげもりみれい、1896〜1975年）が作庭しました。伝統の石組みに市松模様を取り入れた革新的な枯山水で、近代作庭の傑作として高く評価されています。', 2, false),
(5, 19, '庭園の池に設ける、水面上に連続して設置した石のことを何と呼ぶか。', '飛び石（とびいし）', '延段（のべだん）', '沢飛び（さわとび）', '石橋（いしばし）', 2, '沢飛び（さわとび）は池や流れの中に連続して置かれた石で、水を渡るための踏み石です。茶庭（露地）によく使われ、水辺を渡る演出として庭の雰囲気を高める役割があります。', 3, false),
(5, 19, '「枯滝（かれたき）」とは庭園においてどのような表現か。', '水が枯れた本物の滝', '石を積み重ねて滝を表現した枯山水の技法', '枯れ木で作った装飾', '乾燥した砂で作った砂山', 1, '枯滝（かれたき）は石を積み重ねて滝を象徴的に表現する枯山水の技法です。水は使わず石の形・配置で水の流れ・落下を表現し、鑑賞者の想像力に訴えかけます。', 2, false),
(5, 19, '室町時代の銀閣寺（慈照寺）の庭園を整備したとされる花の河原者（かわらもの）の作庭師はだれか。', '重森三玲', '夢窓疎石', '善阿弥', '小堀遠州', 2, '善阿弥（ぜんあみ、?〜1482年）は室町時代の「河原者（かわらもの）」身分の作庭師で、足利義政に重用されました。銀閣寺（慈照寺）の庭園整備に携わり、その技術の高さから義政の信頼を得ました。', 3, false),
(5, 19, '「露地（ろじ）」とは茶道において何を指すか。', '茶室周辺の庭園（茶庭）', '茶道具を収納する場所', '茶の湯の作法書', '茶室の廊下', 0, '露地（ろじ）は茶室を取り囲む庭のことで、「茶庭（ちゃにわ）」とも言います。外露地・内露地に分かれ、飛び石・蹲踞（つくばい）・灯篭などが配置されています。俗世を離れ茶の精神の場へ導く役割があります。', 1, false),
(5, 19, '庭の手水鉢（ちょうずばち）前に置かれる、かがんで手を洗うための低い石は何と呼ぶか。', '役石（やくいし）', '蹲踞石（つくばいいし）', '手水石', '景石（けいせき）', 1, '蹲踞石（つくばいいし）は手水鉢の前に置かれる低い石で、利用者がかがんで（蹲踞=つくばう）手を洗うために置かれます。蹲踞を中心に「海（うみ）」と呼ばれる水受けの石組みが配置されます。', 2, false),
(5, 19, '「大徳寺大仙院（だいとくじだいせんいん）」の石庭を作庭した人物はだれか。', '古岳宗亘（こがくそうこう）', '夢窓疎石', '重森三玲', '小堀遠州', 0, '大徳寺大仙院の枯山水庭園は室町時代の1513年頃、住職の古岳宗亘（こがくそうこう）が作庭したと伝わります。滝・川の流れを石と砂で表現した傑出した枯山水で、重要文化財に指定されています。', 3, false),
(5, 19, '庭園における「蓬莱石組（ほうらいいしぐみ）」とはどのような石組みか。', '海の荒波を表す石組み', '中国の神仙思想に基づく蓬莱山（不老不死の仙境）を表す石組み', '仏教の須弥山を表す石組み', '龍の姿を表す石組み', 1, '蓬莱石組（ほうらいいしぐみ）は中国の神仙思想に基づき、不老不死の仙人が住む「蓬莱山」を石・岩・砂で表現した庭園の石組みです。鶴島・亀島を池に配する「蓬莱式庭園」と組み合わせることが多いです。', 3, false),
(5, 19, '「池泉観賞式庭園（ちせんかんしょうしきていえん）」の特徴として正しいのはどれか。', '庭の中を歩き回る回遊式', '建物（書院・縁側）から座って鑑賞する固定の視点からの庭', '水と石を使わない乾燥した庭', '水田に近い形式の庭', 1, '池泉観賞式庭園は書院・縁側などの建物から座ったまま一定の視点で池泉庭園を鑑賞する様式です。回遊式と異なり歩き回ることを前提としていません。平安・鎌倉時代の寝殿造建築の庭に多く見られます。', 2, false),
(5, 19, '日本庭園で「枯流れ（かれながれ）」とはどのような表現か。', '枯れた木が流れた様子', '石と白砂で川・流れを表した枯山水の要素', '乾燥した砂漠を模した表現', '苔で覆われた緩やかな傾斜', 1, '枯流れ（かれながれ）は白砂・砂利などで川や流れを表現した枯山水の技法です。熊手などで砂に波紋や流れを描き、水の流れを視覚的に表します。龍安寺の石庭の白砂もこの手法のひとつです。', 2, false),
(5, 19, '京都で「苔寺」として有名な世界遺産の寺はどれか。', '南禅寺', '西芳寺（さいほうじ）', '天龍寺', '東福寺', 1, '西芳寺（さいほうじ、通称・苔寺）は世界遺産に登録された臨済宗の寺院で、境内の約120種の苔が一面を覆う景観が有名です。夢窓疎石が14世紀に整備した庭園で、事前申込みが必要です。', 1, false),
(5, 19, '重森三玲が東福寺方丈庭園で用いた独創的なデザインとして有名なのはどれか。', '水面の石橋', '市松模様（チェッカーパターン）の敷石と苔', '水の流れを表す白砂の渦巻き', '中央に大きな岩山を据えた構成', 1, '重森三玲は東福寺方丈の南庭で、切り石と苔を交互に配した市松模様の敷石を導入しました。伝統の石組みと大胆な幾何学模様を組み合わせた革新的なデザインは昭和の近代作庭の代表作として知られます。', 2, false),
(5, 19, '庭に使われる自然石の中で「六方石（ろっぽうせき）」として知られる石の特徴はどれか。', '六面体に人工的に切り出した石', '自然に六角形の断面を持つ玄武岩', '六地蔵の形を刻んだ石', '六カ所から採取した石の組み合わせ', 1, '六方石（ろっぽうせき）は玄武岩が冷える際に自然に形成される六角柱状の節理を持つ石です。自然の造形物として庭園の飛び石・敷石・石組みなどに多用されます。東尋坊（福井）などでも見られる地質現象です。', 3, false);

